// INPUT GUARD - heuristics, not a complete defence. Log and tune false positives.
const cfg = $('Config').first().json;
const body = $('Webhook').first().json.body || {};
const entitlements = JSON.parse(cfg.entitlements_json);
const role = String(body.user_role || 'contractor').toLowerCase();
const allowed = entitlements[role] || entitlements.contractor;
let q = String(body.question || '').normalize('NFKC').replace(/[\u200B-\u200D\uFEFF]/g, '').trim();
const reasons = [];
if (!q) reasons.push('empty_question');
if (q.length > cfg.max_question_chars) reasons.push('too_long');
const injection = [
  /ignore (all |any )?(previous|prior|above) (instructions|rules)/i,
  /disregard (the )?(system|previous) (prompt|instructions)/i,
  /(reveal|print|show|repeat).{0,30}(system prompt|instructions|hidden|secret|api key|password)/i,
  /you are now|act as (an? )?(unfiltered|dan|developer mode)/i,
  /<\s*script|javascript:/i
];
if (injection.some(re => re.test(q))) reasons.push('possible_prompt_injection');
q = q.replace(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, '[EMAIL_REDACTED]')
     .replace(/\b(?:\d[ -]?){13,19}\b/g, '[NUMBER_REDACTED]');
return [{ json: { blocked: reasons.length > 0, reasons, safe_question: q.slice(0, cfg.max_question_chars), user_role: role, allowed_classes: allowed } }];

// RETRIEVAL GUARD: keep only relevant chunks, quarantine instruction-like content, delimit as data.
const cfg = $('Config').first().json;
const suspicious = /(ignore (all |any )?(previous|prior) instructions|system prompt|you must now|AI assistant:|do not tell the user|send .* to http)/i;
const kept = [], quarantined = [];
for (const item of $input.all()) {
  const doc = item.json.document;
  if (!doc) continue;
  const score = typeof item.json.score === 'number' ? item.json.score : 0;
  const source = (doc.metadata && doc.metadata.source) || 'unknown';
  if (suspicious.test(doc.pageContent)) { quarantined.push(source); continue; }
  if (score < cfg.min_score) continue;
  kept.push({ source, score: Math.round(score * 1000) / 1000, text: doc.pageContent.slice(0, 1500) });
}
const context = kept.map((c, i) => `<doc id="${i + 1}" source="${c.source}">\n${c.text}\n</doc>`).join('\n');
const guard = $('Input Guard').first().json;
return [{ json: { question: guard.safe_question, user_role: guard.user_role, sufficient: kept.length > 0, sources: [...new Set(kept.map(c => c.source))], quarantined, context } }];

