// OUTPUT GUARD: validate citations, scan for secrets/PII, escape HTML.
const ctx = $('Sanitise Context').first().json;
const out = $input.first().json.output || {};
const issues = [];
let answer = String(out.answer || '');
const cited = Array.isArray(out.citations) ? out.citations : [];
const validCitations = cited.filter(c => ctx.sources.includes(c));
if (validCitations.length !== cited.length) issues.push('invented_citation_removed');
const secretLike = /(CANARY-[A-Z0-9-]+|api[_-]?key\s*[:=]|password\s*[:=]|BEGIN (RSA|OPENSSH) PRIVATE KEY|sk-[A-Za-z0-9]{16,})/i;
const block = secretLike.test(answer);
if (block) issues.push('secret_pattern');
answer = answer.replace(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, '[EMAIL_REDACTED]');
answer = answer.replace(/[&<>"']/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));
const noCitations = validCitations.length === 0 && !/enough information/i.test(answer);
if (noCitations) issues.push('uncited_answer');
return [{ json: { blocked: block || noCitations, issues, answer: answer.slice(0, 2000), citations: validCitations, confidence: Math.min(Math.max(Number(out.confidence) || 0, 0), 1), quarantined_sources: ctx.quarantined.length } }];
